import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"Orrery i18n Style Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guides/i18n-style-guide.md","filePath":"guides/i18n-style-guide.md"}'),n={name:"guides/i18n-style-guide.md"};function s(d,t,i,l,c,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="orrery-i18n-style-guide" tabindex="-1">Orrery i18n Style Guide <a class="header-anchor" href="#orrery-i18n-style-guide" aria-label="Permalink to &quot;Orrery i18n Style Guide&quot;">​</a></h1><p><em>The rules for every language, UI and content. v1 · 2026-10-30</em></p><blockquote><p>Required reading before translating any locale, by hand or by model. This is the one rules document: the <a href="./i18n-translation-strategy">translation strategy</a> keeps the reasoning, dates and history behind each rule (§3 there is the full text of the name rulings summarised in §2 here); code copies of the rules (<code>NAME_POLICY</code>, <code>BASE_RULES</code>, <code>LOCALE_RULES</code> in <code>scripts/lib/translate-quality.mjs</code>) must agree with this file. Updates here trigger re-translation of affected files (ADR-033).</p></blockquote><hr><h2 id="how-to-use-this-guide" tabindex="-1">How to use this guide <a class="header-anchor" href="#how-to-use-this-guide" aria-label="Permalink to &quot;How to use this guide&quot;">​</a></h2><p>You are translating Orrery into a new language. Before you start:</p><ol><li>Read <strong>§1 Universal symbols</strong> — these are never translated. Use the symbol literally in every language.</li><li>Read <strong>§2 Names and terms</strong> — vehicles and missions by the origin rule; science terms, places and people native in your language; one name per thing.</li><li>Use <strong>§3 + §4</strong> as a binding glossary. The accepted-convention column for your language is the source of truth; pick from the column rather than translating the English literally.</li><li>If your language column is empty (you&#39;re the first translator for it), populate it as you go and submit those decisions for review with the translation pass.</li><li><strong>Citation column</strong> points at the source authority for the term (ESA glossary, NASA Spanish-language style guide, JAXA glossary, etc.). Cite where possible; defer to authoritative sources over LLM judgement.</li></ol><p>Files you will be touching:</p><ul><li><code>messages/&lt;code&gt;.json</code> — Paraglide UI strings (informal register where the en-US source uses a friendly tone; UI labels follow §4a).</li><li><code>i18n-src/&lt;code&gt;/&lt;surface&gt;/…json</code> — per-entity content overlays mirroring <code>i18n-src/en-US/</code> (missions, fleet, programs, science, sites, …), bundled at build into <code>static/data/i18n/&lt;code&gt;.json</code>. Keep every <code>id</code>; names follow §2.</li><li><code>scripts/i18n-tools/native-terms.json</code> — the glossary: native forms of names and terms per locale. A name goes there before it goes into any text (strategy §3.5).</li></ul><p>Per ADR-017&#39;s fallback chain, any key you omit will fall back to en-US — broken translation is bounded, not user-blocking.</p><hr><h2 id="§1-universal-symbols-never-translated" tabindex="-1">§1 Universal symbols (NEVER translated) <a class="header-anchor" href="#§1-universal-symbols-never-translated" aria-label="Permalink to &quot;§1 Universal symbols (NEVER translated)&quot;">​</a></h2><p>These render as the symbol in every language. A native-language gloss is allowed <em>on first use only</em> if helpful for non-technical readers.</p><table tabindex="0"><thead><tr><th>Symbol</th><th>What it means</th><th>Notes</th></tr></thead><tbody><tr><td><code>Δv</code> (delta-v)</td><td>Change in velocity, the standard mission-energy budget</td><td>Universal across every space agency&#39;s literature</td></tr><tr><td><code>Isp</code></td><td>Specific impulse (rocket engine efficiency)</td><td>Universal abbreviation; spelled out as needed in editorial prose</td></tr><tr><td><code>C₃</code></td><td>Characteristic energy (escape-trajectory energy)</td><td>Universal symbol</td></tr><tr><td><code>g</code></td><td>Earth surface gravity (9.81 m/s²)</td><td>Universal</td></tr></tbody></table><p>SI unit symbols (km, s, kg, N, K, km/s …) stay in Latin script in every locale except where the language writes them in its own script (ru км/с, км; ar كم/ث). Number <em>formatting</em> (1,000.5 vs 1.000,5) is handled by <code>Intl.NumberFormat</code> and is automatic per locale; translators never format numbers in strings.</p><h3 id="§1a-astronomy-units-per-locale" tabindex="-1">§1a Astronomy units per locale <a class="header-anchor" href="#§1a-astronomy-units-per-locale" aria-label="Permalink to &quot;§1a Astronomy units per locale&quot;">​</a></h3><p>Astronomy units are <strong>not</strong> universal symbols: each language writes the abbreviation its own sources use (checked against each language&#39;s Wikipedia article, 2026-10-30). Where that language has no settled short form, write the word (light-year → Lichtjahr, 光年). The IAU symbol since 2012 is <code>au</code>; several languages kept a national abbreviation.</p><table tabindex="0"><thead><tr><th>Locale</th><th>astronomical unit</th><th>light-year (short)</th><th>parsec</th><th>km/s</th><th>Evidence (that language&#39;s Wikipedia)</th></tr></thead><tbody><tr><td>en-US</td><td>AU</td><td>ly</td><td>pc</td><td>km/s</td><td>—</td></tr><tr><td>es</td><td>au</td><td>the word (año luz)</td><td>pc</td><td>km/s</td><td>&quot;abreviada au, ua, AU o UA&quot;; ly / al split evenly</td></tr><tr><td>fr</td><td>au</td><td>al</td><td>pc</td><td>km/s</td><td>au 40× vs ua 6×; &quot;année-lumière (symbole al)&quot;</td></tr><tr><td>de</td><td>AE</td><td>the word (Lichtjahr)</td><td>pc</td><td>km/s</td><td>&quot;abgekürzt AE, international au&quot;; no Lj in the article</td></tr><tr><td>pt-BR</td><td>au</td><td>the word (ano-luz)</td><td>pc</td><td>km/s</td><td>&quot;símbolo: au&quot;</td></tr><tr><td>it</td><td>au</td><td>the word (anno luce)</td><td>pc</td><td>km/s</td><td>&quot;simbolo ufficiale: au&quot;; &quot;ly o al&quot;</td></tr><tr><td>nl</td><td>AE</td><td>the word (lichtjaar)</td><td>pc</td><td>km/s</td><td>&quot;astronomische eenheid (AE, internationaal au of ua)&quot;</td></tr><tr><td>zh-CN</td><td>AU</td><td>光年</td><td>pc</td><td>km/s</td><td>&quot;缩写的标准符号为AU&quot;</td></tr><tr><td>ja</td><td>au</td><td>光年</td><td>pc</td><td>km/s</td><td>&quot;記号: au&quot;</td></tr><tr><td>ko</td><td>AU</td><td>광년</td><td>pc</td><td>km/s</td><td>AU used in the parsec article</td></tr><tr><td>hi</td><td>AU</td><td>the word (प्रकाश-वर्ष)</td><td>pc</td><td>km/s</td><td>&quot;AU या au …&quot;</td></tr><tr><td>ar</td><td>و.ف</td><td>the word (سنة ضوئية)</td><td>pc</td><td>كم/ث</td><td>&quot;يرمز لها «و.ف»&quot;; the m/s article writes م\\ث (slash form normalised here)</td></tr><tr><td>ru</td><td>а. е.</td><td>св. год</td><td>пк</td><td>км/с</td><td>&quot;русское обозначение: а. е.&quot;, &quot;св. год&quot;, &quot;пк&quot;, &quot;м/с&quot;</td></tr><tr><td>sr-Cyrl</td><td>АЈ</td><td>the word (светлосна година); next to a variable number св. год. (the word cannot agree with every number)</td><td>pc</td><td>km/s</td><td>&quot;Астрономска јединица (АЈ)&quot;; SI symbols in Latin</td></tr></tbody></table><p>The symbol column is for the unit next to a quantity: &quot;1,5 au&quot;, &quot;(au)&quot;, &quot;en au&quot;, &quot;des dizaines d&#39;au&quot;. Where a sentence names the unit as a noun with an article (fr &quot;l&#39;UA&quot;, es &quot;la UA&quot;, it &quot;l&#39;UA&quot;), the abbreviation stays as written; fr, es, it and pt-BR were switched from <code>UA</code> to <code>au</code> on 2026-10-31 on that basis (operator decision, option 1: only these four locales). Not the University of Arizona in &quot;NASA/UA HiRISE&quot;.</p><p>Light-time shorthand (<code>l-min</code>, light-minutes) follows the light-year column: the language&#39;s own short form where it has one (zh-CN/ja 光分, ko 광분 — the forms already shipping, not separately sourced), otherwise the word. Code that prints a unit next to a number takes the form from a message, never a hard-coded English abbreviation.</p><hr><h2 id="§2-names-and-terms-operator-rulings-2026-10-17-—-see-the-translation-strategy-§3" tabindex="-1">§2 Names and terms (operator rulings 2026-10-17 — see the <a href="./i18n-translation-strategy">translation strategy</a> §3) <a class="header-anchor" href="#§2-names-and-terms-operator-rulings-2026-10-17-—-see-the-translation-strategy-§3" aria-label="Permalink to &quot;§2 Names and terms (operator rulings 2026-10-17 — see the [translation strategy](i18n-translation-strategy.md) §3)&quot;">​</a></h2><p><strong>Things people built — origin rule.</strong> Missions, spacecraft, rockets, stations, modules, programs, agencies, companies, design bureaus: English in every language, <strong>except the language of the name&#39;s origin</strong>, which uses the original name (ru «Союз МС-24», «Мир», «Протон-М»; zh-CN 神舟, 嫦娥五号; Iranian names in Arabic script in <code>ar</code>). Agencies keep their international acronym (NASA stays NASA), except in the agency&#39;s own language, which uses the local name its own Wikipedia uses: hi इसरो, ru Роскосмос, zh-CN 国家航天局, ar مركز محمد بن راشد للفضاء; ja keeps JAXA (ja sources write JAXA). When unsure: इसरो (ISRO). Code: <code>ORIGIN_NAMES</code> in <code>src/lib/name-origins.js</code>; glossary class <code>agency</code> in <code>scripts/i18n-tools/native-terms.json</code>.</p><p><strong>Latin names never take a case ending in Cyrillic text</strong> (ru, sr-Cyrl): no &quot;NASA-ин&quot;, &quot;Voyager-а&quot;. A common noun before the name carries the ending (ru агентства NASA, аппарата Voyager 2; sr агенције NASA, летелице Voyager 2), or reword.</p><p><strong>Science, geography, astronomy and people — native in every language,</strong> written the way that country&#39;s universities, schools and space agency write them: planets and moons, eponymous terms (законы Кеплера, сфера Хилла, эффект Оберта), term abbreviations (НОО for LEO), Moon/planet features, stars, constellations, galaxies, places, and people&#39;s names (Кеплер, ケプラー, 开普勒; fr Iouri Gagarine). Unsure → search the term in that language and use the form native pages use. The per-locale forms are in <code>scripts/i18n-tools/native-terms.json</code>.</p><p><strong>One thing, one name per language.</strong> The form on the thing&#39;s own page (fleet, program, mission, body, site) is canonical; every mention in articles and editorials uses it.</p><p><strong>Exceptions and edge cases</strong> (each stated once, here):</p><ul><li><strong>Publications and sources</strong> (journals, websites, reports, societies cited as a source — Nature, Icarus, NASA Solar System Exploration) stay exactly as in English (<code>NAME_POLICY</code> point 2).</li><li><strong>The International Space Station is a term, not a name</strong>: each language&#39;s own abbreviation (ru МКС, sr-Cyrl МСС, es/pt-BR EEI, it SSI; ISS where its sources write ISS). Strategy §3.2 has the full list.</li><li><strong>Museums and observatories are institutions, not built things</strong>: native form in every locale, like the facility glossary (<code>translate-quality.mjs</code> surface list). sr-Cyrl goes further (operator decision 2026-10-22): a museum or observatory with no Serbian form is transliterated phonetically into Cyrillic (&quot;Космосфера&quot;), cities likewise; the Serbian form wins where one exists (&quot;Технички музеј Шпајер&quot;). Vehicle designations inside them stay as §2.</li><li><strong>Russian running text</strong> puts vehicle names in «» quotes; headings don&#39;t.</li></ul><p>This supersedes the 2026-10-17-morning ruling that kept every name in Latin script. The rules ship in code as <code>NAME_POLICY</code> and <code>problems()</code> (<code>scripts/lib/translate-quality.mjs</code>).</p><h3 id="mission-names" tabindex="-1">Mission names <a class="header-anchor" href="#mission-names" aria-label="Permalink to &quot;Mission names&quot;">​</a></h3><p>Rationale: missions are real-world objects with single canonical names. A user searching for &quot;Curiosity&quot; in Spanish documentation should still find &quot;Curiosity&quot;, not &quot;Curiosidad&quot;. (The origin language uses the original name instead — §2 above: ru «Луна-9», zh-CN 嫦娥四号.)</p><p>The form below is the one used <strong>outside the origin language</strong>; &quot;keep&quot; means keep it as written here, not translate it.</p><table tabindex="0"><thead><tr><th>Mission</th><th>Form outside the origin language</th></tr></thead><tbody><tr><td>All NASA Mars rovers</td><td>Curiosity, Perseverance, Sojourner, Spirit, Opportunity (English; keep)</td></tr><tr><td>Apollo programme</td><td>Apollo 11, Apollo 17, Artemis II, Artemis III (keep numerals + name)</td></tr><tr><td>ISRO</td><td>Chandrayaan-1, Chandrayaan-3, Mangalyaan / Mars Orbiter Mission (keep both names where dual-named)</td></tr><tr><td>CNSA</td><td>Tianwen-1, Chang&#39;e 4 / 5 / 6 (keep apostrophes + numerals)</td></tr><tr><td>JAXA</td><td>Hayabusa, SLIM (keep romanisation)</td></tr><tr><td>Roscosmos</td><td>Luna 9 / 17 / 24, Mars 3 (keep)</td></tr><tr><td>ESA</td><td>Mars Express (keep)</td></tr><tr><td>MBRSC (UAE)</td><td>Hope Probe (keep English)</td></tr><tr><td>SpaceX</td><td>Starship (keep)</td></tr><tr><td>Blue Origin</td><td>Blue Moon MK1 (keep)</td></tr><tr><td>Tito concept</td><td>Inspiration Mars (keep)</td></tr></tbody></table><h3 id="agency-proper-nouns-international-acronym-local-name-in-the-agency-s-own-language" tabindex="-1">Agency proper nouns (international acronym; local name in the agency&#39;s own language) <a class="header-anchor" href="#agency-proper-nouns-international-acronym-local-name-in-the-agency-s-own-language" aria-label="Permalink to &quot;Agency proper nouns (international acronym; local name in the agency&#39;s own language)&quot;">​</a></h3><p>NASA, ESA, JAXA, ISRO, CNSA, ROSCOSMOS, UAESA, AEB, KARI, CSA, UKSA, ASI, DLR, CNES, MBRSC. Do <strong>not</strong> expand or translate the acronyms — except in the agency&#39;s own language, which writes its local name (hi इसरो, ru Роскосмос, zh-CN 国家航天局, ar مركز محمد بن راشد للفضاء; see §2). Check that language&#39;s Wikipedia before adding another: ja.wikipedia writes JAXA, so ja keeps JAXA.</p><hr><h2 id="§3-translatable-astronomy-orbital-mechanics-terms" tabindex="-1">§3 Translatable astronomy + orbital-mechanics terms <a class="header-anchor" href="#§3-translatable-astronomy-orbital-mechanics-terms" aria-label="Permalink to &quot;§3 Translatable astronomy + orbital-mechanics terms&quot;">​</a></h2><p>The English column is the source. The accepted-convention column for your target language is the <strong>binding</strong> translation. Cite source where given.</p><p>For the technical terms in the glossary&#39;s <code>term</code> class (<code>scripts/i18n-tools/native-terms.json</code>: orbit, trajectory, apogee, perigee, burn, flyby, orbit insertion, entry, descent and the rest of the pilot&#39;s 20), the binding form for all 13 locales lives there. <code>term-drift.mjs</code> checks it. A row here that covers the same term must agree with it (checked for es on 2026-10-31: sobrevuelo, inserción orbital, apogeo, perigeo).</p><table tabindex="0"><thead><tr><th>English</th><th><code>es</code> (Spanish)</th><th><code>fr</code></th><th><code>de</code></th><th><code>pt-BR</code></th><th><code>it</code></th><th><code>sr-Cyrl</code></th><th>Source</th></tr></thead><tbody><tr><td>aphelion</td><td>afelio</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>perihelion</td><td>perihelio</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>apogee</td><td>apogeo</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>perigee</td><td>perigeo</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>eccentricity</td><td>excentricidad</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>true anomaly</td><td>anomalía verdadera</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish glossary</td></tr><tr><td>line of apsides</td><td>línea de los ápsides</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish glossary</td></tr><tr><td>free-return (trajectory)</td><td>trayectoria de retorno libre</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-MSFC Spanish</td></tr><tr><td>sphere of influence (SOI)</td><td>esfera de influencia</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish glossary</td></tr><tr><td>porkchop plot</td><td>diagrama porkchop <em>(no Spanish equivalent in wide use)</em></td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish glossary uses English</td></tr><tr><td>Astronomical Unit</td><td>unidad astronómica (au)</td><td>unité astronomique (au)</td><td>Astronomische Einheit (AE)</td><td>unidade astronômica (au)</td><td>unità astronomica (au)</td><td>астрономска јединица (АЈ)</td><td>§1a</td></tr></tbody></table><p>Empty cells are populated by the translator for that language ticket.</p><hr><h2 id="§4-translatable-mission-domain-terms" tabindex="-1">§4 Translatable mission-domain terms <a class="header-anchor" href="#§4-translatable-mission-domain-terms" aria-label="Permalink to &quot;§4 Translatable mission-domain terms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th><code>es</code></th><th><code>fr</code></th><th><code>de</code></th><th><code>pt-BR</code></th><th><code>it</code></th><th>Source</th></tr></thead><tbody><tr><td>launch window</td><td>ventana de lanzamiento</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-JPL Spanish</td></tr><tr><td>transit (cruise phase)</td><td>tránsito</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish</td></tr><tr><td>flyby</td><td>sobrevuelo</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish</td></tr><tr><td>orbit insertion</td><td>inserción orbital</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish</td></tr><tr><td>LOI (lunar orbit insertion)</td><td>inserción en órbita lunar (IOL)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-MSFC Spanish</td></tr><tr><td>MOI (Mars orbit insertion)</td><td>inserción en órbita marciana (IOM)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish</td></tr><tr><td>EDL (entry, descent, landing)</td><td>EDA (entrada, descenso, aterrizaje)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-JPL Spanish</td></tr><tr><td>TLI (trans-lunar injection)</td><td>inyección translunar (ITL)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-MSFC Spanish</td></tr><tr><td>TMI (trans-Mars injection)</td><td>inyección transmarciana (ITM)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish</td></tr><tr><td>TCM (trajectory correction manoeuvre)</td><td>maniobra de corrección de trayectoria (MCT)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-JPL Spanish</td></tr><tr><td>splashdown</td><td>amerizaje</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>rendezvous</td><td>acoplamiento <em>(when docking)</em> / encuentro <em>(when proximity)</em></td><td>—</td><td>—</td><td>—</td><td>—</td><td>ESA Spanish</td></tr><tr><td>heliocentric</td><td>heliocéntrico</td><td>—</td><td>—</td><td>—</td><td>—</td><td>RAE</td></tr><tr><td>cislunar</td><td>cislunar</td><td>—</td><td>—</td><td>—</td><td>—</td><td>NASA-MSFC Spanish</td></tr></tbody></table><hr><h2 id="§4a-ui-labels-buttons-tabs-chips-status-words-aria-labels" tabindex="-1">§4a UI labels (buttons, tabs, chips, status words, aria-labels) <a class="header-anchor" href="#§4a-ui-labels-buttons-tabs-chips-status-words-aria-labels" aria-label="Permalink to &quot;§4a UI labels (buttons, tabs, chips, status words, aria-labels)&quot;">​</a></h2><p>Short UI strings fail differently from prose: there is no sentence to carry the meaning, so a literal or transliterated word slips through (shipped examples found 2026-10-30: ja &quot;クローズパネル&quot; and ar &quot;حلقة مغلقة&quot; &quot;closed loop&quot; for &quot;Close panel&quot;; ru &quot;Играть&quot; &quot;play a game&quot; for media Play; ko &quot;닫기 패널&quot; in the wrong order).</p><ul><li><p><strong>Translate the action in context.</strong> Read the key name and where it is used (<code>grep</code> the key in <code>src/</code>) before writing it. Play = start playback; Close = close this panel; Reset = return to the default.</p></li><li><p><strong>Never transliterate an English word</strong> into the script (no katakana &quot;クローズ&quot;, no Cyrillic &quot;ресетуј&quot; where the language has its own verb — except where that language&#39;s own UI convention uses the loan word).</p></li><li><p><strong>Command form</strong>, taken from the correct shipped strings (the ja / ko / hi / ar &quot;Close panel&quot; examples are corrections of the defects above, not shipped yet):</p><table tabindex="0"><thead><tr><th>Locale</th><th>Form</th><th>Example (Close panel / Reset view)</th></tr></thead><tbody><tr><td>es, fr, de, pt-BR, nl, ru</td><td>infinitive</td><td>Cerrar panel · Fermer le panneau · Panel schließen · Fechar painel · Paneel sluiten · Закрыть панель</td></tr><tr><td>it, sr-Cyrl</td><td>imperative</td><td>Chiudi pannello · Затвори панел</td></tr><tr><td>zh-CN</td><td>verb + object</td><td>关闭面板 · 重置视图</td></tr><tr><td>ja</td><td>object を + verb (dictionary form)</td><td>パネルを閉じる · ビューをリセット</td></tr><tr><td>ko</td><td>object + verbal noun</td><td>패널 닫기 · 보기 초기화</td></tr><tr><td>hi</td><td>object + polite imperative (-ें)</td><td>पैनल बंद करें · व्यू रीसेट करें</td></tr><tr><td>ar</td><td>verbal noun (maṣdar)</td><td>إغلاق اللوحة · إعادة تعيين العرض</td></tr></tbody></table></li><li><p><strong>Case.</strong> When the English label is UPPERCASE, Latin and Cyrillic locales write it uppercase too; caseless scripts (zh-CN, ja, ko, hi, ar) write it normally.</p></li><li><p><strong>Agreement.</strong> A label that qualifies different nouns gets one key per noun (<code>mission_status_active</code> ACTIVA vs <code>fleet_status_active</code> ACTIVO), never one shared key.</p></li><li><p><strong>Same as English</strong> is allowed only for symbols (§1), units as §1a gives them, the &quot;Orrery&quot; brand, acronyms the language&#39;s own sources use, and the /fly event shorthand keys <code>fly-event-catalog.test.ts</code> pins to English (<code>fly_event_tcm</code>, <code>_edl_or_oi</code>, <code>_anomaly</code>, <code>_loi</code>, <code>_tei</code>).</p></li><li><p><strong>Units next to numbers</strong> come from a message per §1a, never a hard-coded English abbreviation in a component.</p></li><li><p><strong>Read the meaning, not the dictionary word.</strong> The commonest UI defect in the 2026-10-30 audit (the same keys wrong in up to 11 of 13 locales: coast_scrub_aria) was a word taken in its everyday sense: constellation (a satellite fleet, not stars), coast (unpowered flight, not a shore), scrub (drag the slider, not clean), hold (a countdown hold), pinned (a UI action, not a nail), legend (a map key, not a folk tale), launch (a rocket, not a product release), small body (an asteroid, not a person). <code>scripts/i18n-tools/ui-senses.json</code> gives the meaning of every key found this way, and the UI translators send it with the key; add a key when an audit finds a new one.</p></li><li><p><strong>ALL-CAPS labels are words.</strong> STATUS, PERIOD, ARRIVAL, DOCKED are translated like any word (ja shipped スタタス, ペリド, アーリバル). Only real acronyms stay (TLI, LOI, EDL, TCM, C3, ISS).</p></li><li><p><strong>Page titles keep the brand</strong>: &quot;<code>&lt;page&gt; · Orrery</code>&quot;, with &quot;Orrery&quot; in Latin script in every locale (shipped: ja オーラリー, hi ऑररेरी, ar أرّيلي, ru Оррери, zh 奥雷里).</p></li><li><p><strong>Right-to-left arrows.</strong> In ar (and he), &quot;→&quot; next to words points backwards, because bidi does not mirror arrows: write &quot;←&quot; (&quot;الأرض ← القمر&quot;, a CTA &quot;… ←&quot;). Arrows between Latin symbols in a formula (e→1) stay.</p></li><li><p><strong>One English label, one translation</strong>, unless the meaning really differs (ja 退役 for a retired rocket, 運用終了 for a rover that stopped).</p></li><li><p><strong>Checked automatically.</strong> <code>problems(…, { ui: true })</code> in <code>scripts/lib/translate-quality.mjs</code> rejects ordinary English words left in a non-Latin label, glossary bodies and places left in English, a changed &quot;Orrery&quot; and backwards RTL arrows; <code>scripts/i18n-tools/ui-label-audit.test.ts</code> runs it over every <code>messages/&lt;loc&gt;.json</code> and also fails on a label with a second translation, and on a label whose whole English is a glossary term (a planet, moon, star, place) but whose value lacks the glossary form. Known defects of locales not audited yet are listed in <code>scripts/i18n-tools/ui-label-baseline.json</code>, which only shrinks.</p></li></ul><h3 id="§4b-kept-in-english-on-purpose-—-never-translate-these" tabindex="-1">§4b Kept in English on purpose — never translate these <a class="header-anchor" href="#§4b-kept-in-english-on-purpose-—-never-translate-these" aria-label="Permalink to &quot;§4b Kept in English on purpose — never translate these&quot;">​</a></h3><p>Operator decision (2026-10-30). These stay exactly as written in every locale. A &quot;fix&quot; that translates one of them is a regression:</p><ul><li><strong>Developer panels and debug readouts</strong>: <code>DebugPanel</code>, <code>FlybyDebugViewer</code>, <code>AscentCameraDebug</code>, <code>TargetEnvSwitcher</code>, the <code>label</code> of <code>DebugPanelRegistrar</code> / <code>RenderingDebugRegistrar</code>, anything inside <code>{#if …debug…}</code> or a <code>{#snippet …Debug…}</code> (the /fly Tier-1 and cislunar debug readouts, the coast-camera readout, the surface-scene debug box), and everything under <code>src/routes/dev/</code>.</li><li><strong>Acronyms and codes</strong>: flight-dynamics acronyms (MECO, SECO, MAX-Q, MAX-G, SRB, TLI, TMI, LOI, MOI, EDL, TCM, TEI, Δv, Isp, C3), the /fly toggle row codes (FD, LYR, CON, HUD, CAP — each button&#39;s tooltip is translated), catalogue prefixes (HIP), keyboard key caps (Esc, Enter, ↑ ↓), file extensions.</li><li><strong>Physics Lab canvases</strong>: text drawn on the Lab hero canvases and flight maps (<code>src/lib/lab/*Canvas.svelte</code>, <code>flight-maps.ts</code>), their aria-labels included — ADR-090 &quot;Canvas copy is English&quot;. DOM text around them is translated.</li><li><strong>Audio narration and captions</strong> (<code>src/lib/audio-tour.ts</code>): English-only by decision.</li><li><strong>Names that are not words</strong>: cited source and dataset names (GCAT&#39;s author, Launch Library 2 — The Space Devs, Copernicus Sentinel-2, HiRISE, USGS NAIP …), the contact e-mail, in-world signage on 3D models (ISS module plaques, rocket livery).</li><li><strong>Audio-tour anchors</strong>: the hidden <code>select …</code> buttons (aria-hidden, tabindex −1) the tour script clicks.</li></ul><p>The scan in <code>scripts/i18n-tools/hardcoded-english.mjs</code> skips the developer blocks by structure and lists the rest in <code>hardcoded-english-allowlist.json</code> with the reason; <code>hardcoded-english.test.ts</code> fails on any other English string in Svelte markup.</p><hr><h2 id="§5-tone-register-guidance" tabindex="-1">§5 Tone + register guidance <a class="header-anchor" href="#§5-tone-register-guidance" aria-label="Permalink to &quot;§5 Tone + register guidance&quot;">​</a></h2><ul><li><strong>Educational, friendly, precise.</strong> Orrery is for the curious learner first; physics accuracy second. Translations should match that register.</li><li><strong>Informal &quot;you&quot; where the language distinguishes</strong> (Spanish <code>tú</code>, French <code>tu</code>, German <code>du</code>). The English source uses friendly direct address.</li><li><strong>Active voice</strong> preferred over passive where the language allows naturally.</li><li><strong>Concise</strong> — Spanish runs ~30% longer than English; tighten where possible to avoid layout overflow at 375px.</li><li><strong>Date formatting</strong> is handled by <code>Intl.DateTimeFormat</code> (locale-aware). Do not translate dates in strings.</li><li><strong>Number formatting</strong> handled by <code>Intl.NumberFormat</code>. Do not translate numbers in strings.</li></ul><hr><h2 id="§6-source-authorities" tabindex="-1">§6 Source authorities <a class="header-anchor" href="#§6-source-authorities" aria-label="Permalink to &quot;§6 Source authorities&quot;">​</a></h2><p><strong>Names</strong> (people, places, bodies, features, stars, agencies&#39; local names): the form that language&#39;s own Wikipedia uses, recorded in the glossary first (operator rulings 2026-10-17/18, strategy §3.5). <strong>The site&#39;s existing form wins</strong> when the site already uses one consistently.</p><p><strong>Terms and units</strong>, when contested, defer in this order:</p><ol><li><strong>The space agency&#39;s own glossary</strong> in the target language (ESA Spanish, NASA-JPL Spanish, JAXA Japanese, CNSA Mandarin, etc.).</li><li><strong>The country&#39;s national language academy</strong> for general scientific vocabulary (RAE for Spanish, Académie française for French, Duden for German, Crusca for Italian, Academia Brasileira de Letras for pt-BR).</li><li><strong>Wikipedia in the target language</strong> — what the language&#39;s own sources write (§1a was settled this way).</li><li><strong>Model judgement</strong> only when none of these has the term: record the choice and the reason next to it (glossary entry or a note here).</li></ol><p>Cited source links (populate per language as glossaries are consulted):</p><ul><li>ESA Spanish glossary: <code>https://www.esa.int/Space_in_Member_States/Spain</code> (general portal; search for &quot;glosario&quot;)</li><li>NASA-MSFC Spanish technical reports: NTRS search by <code>language:Spanish</code></li><li>NASA-JPL Spanish-language editorial guidelines: internal; cite via the specific PDF when quoted</li><li>IAU resolutions on astronomical unit: <code>https://www.iau.org/static/resolutions/IAU2012_English.pdf</code></li><li>RAE diccionario: <code>https://dle.rae.es/</code></li></ul><hr><h2 id="§7-what-to-do-when-stuck" tabindex="-1">§7 What to do when stuck <a class="header-anchor" href="#§7-what-to-do-when-stuck" aria-label="Permalink to &quot;§7 What to do when stuck&quot;">​</a></h2><ul><li><strong>Term not in this glossary.</strong> Translate per language convention; add a row to §3 or §4 with the chosen term and a citation.</li><li><strong>Conflicting conventions across sources.</strong> Pick the agency glossary over the language academy; document the conflict in a one-line note.</li><li><strong>English term has no equivalent.</strong> Keep the English term and add an inline gloss on first use (e.g. <code>porkchop plot</code> in Spanish editorial prose).</li><li><strong>Mission name conflict</strong> (e.g. agency uses one romanisation, Wikipedia uses another). Defer to the agency&#39;s official romanisation.</li></ul>',65)])])}const p=e(n,[["render",s]]);export{g as __pageData,p as default};
